def field(label,name,kind='text',help='',**attrs):
    params=' '.join(f'{k}="{escape(str(v),quote=True)}"' for k,v in attrs.items())
    control=f'<textarea id="{name}" name="{name}" rows="4" {params}></textarea>' if kind=='textarea' else f'<input id="{name}" name="{name}" type="{kind}" {params}>'
    return f'<label class="field" for="{name}"><span>{label}</span>{control}'+(f'<small>{help}</small>' if help else '')+'</label>'
brief=field('Product or collection name','name',required='required',maxlength=140)+field('Who is it for, and when will they use it?','audience','textarea')+field('The experience or practical need','intention','textarea')+field('Chosen Aura expressions or values','expressions',help='Use your own words, separated by commas.')+field('Product details and variants','specification','textarea',help='For example: material, size, format, colour or wording. Keep unknowns visible.')
brief+='''<label class="field"><span>Suggestion direction</span><select name="ideasFocus" id="ideasFocus"><option value="">Follow my product idea</option><option value="clothing">Clothing</option><option value="drinks">Drinks</option><option value="collections">Merchandise and club collections</option><option value="mat">Bathroom mats</option><option value="hygiene">Hygiene and care</option><option value="objects">Everyday objects and gifts</option><option value="gatherings">Gatherings and shared experiences</option></select><small>Usually follows your product name and brief. Choose a direction if another set of ideas would help.</small></label>'''

making=field('Materials, ingredients or components','materials','textarea')+field('Sample or specification version','sampleVersion',help='Give each agreed version a name or date.')+field('Maker and dated quotation','maker','textarea',help='Record the actual quote, quantity, inclusions, lead time and source.')+field('Sample observations and next revision','feedback','textarea')+field('People and agreed contributions','contributors','textarea',help='Name the contribution, payment or exchange, and limits of responsibility.')
costs=''.join(field(label,name,'number',min=0,step='0.01') for name,label in [('materialsCost','Materials per item (AUD)'),('labourCost','Labour per item (AUD)'),('packagingCost','Packaging per item (AUD)'),('freightCost','Freight per item (AUD)'),('otherCost','Returns, royalties and other per item (AUD)'),('price','Selling price per item (AUD)'),('fixedCost','Fixed setup cost for this batch (AUD)')])+field('Selling fee (%)','feePercent','number',min=0,max=100,step='0.01')+field('Planned units in the batch','quantity','number',min=1,step=1)
offer=field('What does the customer receive?','offer','textarea')+field('Sales route','salesRoute',help='For example: direct, market, hospitality or wholesale.')+field('Availability, timing and handover','fulfilment','textarea')+field('Terms, minimum batch and cancellation approach','terms','textarea')+field('Audience, message and chosen channels','marketing','textarea')+field('Creative assets, credits and agreed use','creative','textarea')
circle=field('Activity and invitation','community','textarea')+field('Participation and sharing choices','participation','textarea')+field('Care, repair or refill route','care','textarea')+field('Receiving service and acceptance conditions','receiver','textarea')+field('Quantity sent into the return process','sent','number',min=0,step='0.01')+field('Quantity received for another use','returned','number',min=0,step='0.01')+field('Unit being measured','unit',help='Use the same unit for both quantities, such as bottles, items or kilograms.')+field('Actual result, losses and operating costs','nextUse','textarea')
agent=field('Task and intended result','agentTask','textarea')+field('Source records and permitted actions','permissions','textarea')+field('Spending and publication limits','limits','textarea')+field('Person handling exceptions','reviewer')+field('Questions to resolve before action','questions','textarea')
tabs=[('brief','The brief',brief),('making','Making',making),('costs','Costs',f'<p>Enter a consistent estimate in AUD. Leave unknown figures blank. This calculator excludes tax and financing and does not verify quotations.</p><div class="form-grid">{costs}</div><div id="cost-results" class="results" aria-live="polite"></div>{field('Cost assumptions and questions','costNotes','textarea',help='Keep quotes, unknown costs and ideas to investigate here. Suggestions do not fill in prices.')}'),('offer','The offer',offer),('circular','Community & next use',circle+'<div id="return-results" class="note" aria-live="polite"></div>'),('connections','Connections','''<p>Connect this record with several people, projects, materials or other products. Each connection describes an exchange; none creates a parent or rank.</p><div id="connections-list"></div><fieldset class="connection-entry"><legend>Add a connection</legend><label class="field">Name<input id="link-name" maxlength="160"></label><label class="field">Contribution or exchange<input id="link-role" maxlength="300"></label><label class="field">Agreed terms or question to resolve<textarea id="link-terms" rows="3"></textarea></label><label class="field">Link to another saved product<select id="link-target"><option value="">No saved product selected</option></select></label><label class="field">Source URL (optional)<input id="link-url" type="url" placeholder="https://"></label><button type="button" class="btn secondary" id="add-connection">Add connection</button></fieldset>'''),('handoff','Agent handoff',agent+'''<label class="field">Permission status<select id="permissionStatus" name="permissionStatus"><option value="draft">Draft only</option><option value="authorised">Scope recorded as authorised</option><option value="paused">Paused</option><option value="revoked">Revoked</option></select></label><p class="note">This prepares a handoff document. No AI agent runs here, and this status does not execute a payment, order, message or publication.</p>''')]
tab_buttons=''.join(f'<button type="button" role="tab" id="tab-{key}" aria-controls="panel-{key}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-tab="{key}">{label}</button>' for i,(key,label,body) in enumerate(tabs))
panels=''.join(f'<section class="work-panel" role="tabpanel" id="panel-{key}" aria-labelledby="tab-{key}"'+(' hidden' if i else '')+f'><h2>{label}</h2><aside class="ideas-box" id="ideas-{key}" aria-label="Optional starting ideas"></aside>{body}</section>' for i,(key,label,body) in enumerate(tabs))
case_options=''.join(f'<option value="{slug}">{title}</option>' for slug,title,*rest in cases)
body=f'''<section class="work-head"><div class="wrap"><h1>Make an idea workable.</h1><p>Start a blank product or explore a case study. Your records stay in this browser on this device. Export a backup to take them with you.</p></div></section><section class="work-area"><div class="wrap"><div class="work-toolbar"><label class="field">Your saved products<select id="record-select"><option value="">Start a record below</option></select></label><button class="btn secondary" type="button" id="new-record">New blank product</button><label class="field">Explore a case study<select id="case-select"><option value="">Choose a starting idea</option>{case_options}</select></label><button class="btn" type="button" id="open-case">Open case</button></div><div id="app-status" role="status" aria-live="polite">Ready to start. No personal data is sent to a server.</div><div id="empty-state" class="empty-state"><h2>Your next useful thing<br>starts here.</h2><p>Bring your own idea, or open one of Luke’s case studies above. You can connect products and contributions without a fixed hierarchy.</p><button class="btn" type="button" id="empty-new">Create a blank product ↗</button></div><div id="editor" hidden><div class="record-bar"><div><h2 id="record-heading"></h2><p id="record-meta"></p></div><div class="actions"><button class="btn" type="button" id="save-record">Save record</button><button class="btn secondary" type="button" id="export-pack">Export release pack</button></div></div><p id="case-notice" class="note" hidden></p><div class="workspace"><div class="work-tabs" role="tablist" aria-label="Product record sections">{tab_buttons}</div><form id="product-form">{panels}</form></div><details class="history"><summary>Version history</summary><div id="history-list"></div></details><div class="record-actions"><button type="button" id="duplicate-record" class="text-button">Duplicate this product</button><button type="button" id="delete-record" class="text-button">Delete this product</button></div></div><div class="backup-bar"><div><h3>Your work travels with you.</h3><p>Download a full JSON backup, or import one to restore your records. Browser storage can be cleared by your device or browser.</p></div><div class="actions"><button class="btn secondary" id="backup" type="button">Download backup</button><label class="btn secondary" for="import-file">Import backup</label><input id="import-file" type="file" accept="application/json,.json" class="sr-only"></div></div></div></section><section class="section compact green"><div class="wrap split"><div><h2>Working here today</h2><p>Editable briefs, connected records, transparent costing, material return tracking, version snapshots and portable exports.</p></div><div><h2>Still to connect</h2><p>Shared accounts, live AI agents, verified suppliers, payments, stock systems and publication services. This workbench prepares records and plans; it does not place orders or make commitments.</p></div></div></section>'''
add('workbench.html','Product workbench','Create local product records, explore case studies, compare costs and export a connected release pack.',body)
